11: /** Stores the data needed to make a template update. */
12: export interface Update {
13:   /** The location of the update. */
14:   location: compiler.ParseLocation;
15: 
16:   /** A function to be used to update the template. */
17:   updateFn: (html: string) => string;
18: }
