20: export abstract class TemplateMigrator {
21:   /** Stores template updates. By default gets returned by #getUpdates. */
22:   protected updates: Update[] = [];
23: 
24:   /** Preorder callback hook for the template AST traversal. */
25:   preorder(node: compiler.TmplAstElement): void {}
26: 
27:   /** Postorder callback hook for the template AST traversal. */
28:   postorder(node: compiler.TmplAstElement): void {}
29: 
30:   /** Returns the data needed to update the given node. */
31:   getUpdates(): Update[] {
32:     return this.updates;
33:   }
34: 
35:   /** Runs once a template has finished being updated. */
36:   reset(): void {
37:     this.updates = [];
38:   }
39: }

