56: /**
57:  * Replaces the start tag of the given Element node inside of the html document with a new tag name.
58:  *
59:  * @param html The full html document.
60:  * @param node The Element node to be updated.
61:  * @param tag A new tag name.
62:  * @returns an updated html document.
63:  */
64: export function replaceStartTag(html: string, node: compiler.TmplAstElement, tag: string): string {
65:   return replaceAt(html, node.startSourceSpan.start.offset + 1, node.name, tag);
66: }
67: 
68: /**
69:  * Replaces the end tag of the given Element node inside of the html document with a new tag name.
70:  *
71:  * @param html The full html document.
72:  * @param node The Element node to be updated.
73:  * @param tag A new tag name.
74:  * @returns an updated html document.
75:  */
76: export function replaceEndTag(html: string, node: compiler.TmplAstElement, tag: string): string {
77:   if (!node.endSourceSpan) {
78:     return html;
79:   }
80:   return replaceAt(html, node.endSourceSpan.start.offset + 2, node.name, tag);
81: }
82: 
83: /**
84:  * Appends an attribute to the given node of the template html.
85:  *
86:  * @param html The template html to be updated.
87:  * @param node The node to be updated.
88:  * @param name The name of the attribute.
89:  * @param value The value of the attribute.
90:  * @returns The updated template html.
91:  */
92: export function addAttribute(
93:   html: string,
94:   node: compiler.TmplAstElement,
95:   name: string,
96:   value: string,
97: ): string {
98:   const index = node.startSourceSpan.start.offset + node.name.length + 1;
99:   const prefix = html.slice(0, index);
100:   const suffix = html.slice(index);
101: 
102:   if (node.startSourceSpan.start.line === node.startSourceSpan.end.line) {
103:     return prefix + ` ${name}="${value}"` + suffix;
104:   }
105: 
106:   const attr = node.attributes[0];
107:   const ctx = attr.sourceSpan.start.getContext(attr.sourceSpan.start.col + 1, 1)!;
108:   const indentation = ctx.before;
109: 
110:   return prefix + indentation + `${name}="${value}"` + suffix;
111: }
