9: import {Migration, ResolvedResource} from '@angular/cdk/schematics';
10: import {SchematicContext} from '@angular-devkit/schematics';
11: import {visitElements, parseTemplate} from './tree-traversal';
12: import {ComponentMigrator} from '.';
13: import {Update} from './template-migrator';
14: 
15: export class TemplateMigration extends Migration<ComponentMigrator[], SchematicContext> {
16:   enabled = true;
17: 
18:   override visitTemplate(template: ResolvedResource) {
19:     const ast = parseTemplate(template.content, template.filePath);
20:     const migrators = this.upgradeData.filter(m => m.template).map(m => m.template!);
21:     const updates: Update[] = [];
22: 
23:     visitElements(
24:       ast.nodes,
25:       node => migrators.forEach(m => m.preorder(node)),
26:       node => migrators.forEach(m => m.postorder(node)),
27:     );
28: 
29:     migrators.forEach(m => updates.push(...m.getUpdates()));
30:     updates.sort((a, b) => b.location.offset - a.location.offset);
31:     updates.forEach(update => {
32:       template.content = update.updateFn(template.content);
33:     });
34: 
35:     migrators.forEach(m => m.reset());
36:     this.fileSystem.overwrite(template.filePath, template.content);
37:   }
38: }

