export class ChipsTemplateMigrator extends TemplateMigrator {
  /** The matChipInputFor attributes found while traversing the template ast. */
  private _chipInputAttrs: compiler.TmplAstBoundAttribute[] = [];

  /** The mat-chip-list nodes found while traversing the template ast. */
  private _chipLists: compiler.TmplAstElement[] = [];

  /** The mat-chip nodes found while traversing the template ast. */
  private _chips: compiler.TmplAstElement[] = [];

  override preorder(node: compiler.TmplAstElement): void {
    switch (node.name) {
      case 'mat-chip-list':
        this._chipLists.push(node);
        break;
      case 'mat-chip':
        this._chips.push(node);
        break;
      case 'input':
        this._storeChipRefs(node);
        break;
    }
  }

  override getUpdates(): Update[] {
    // Track the chips that are nested within a mat-chip-list so that standalone
    // chips can be handled separately from grouped chips.
    const nestedChips = new Set<compiler.TmplAstElement>();

    this._chipLists.forEach(chipList => {
      this.updates.push(
        ...this._buildUpdates(chipList, chipList, 'mat-chip-grid', 'mat-chip-listbox'),
      );

      const chips: compiler.TmplAstElement[] = [];
      this._collectNestedChips(chipList, chips);
      chips.forEach(chip => {
        nestedChips.add(chip);
        this.updates.push(
          ...this._buildUpdates(chip, chipList, 'mat-chip-row', 'mat-chip-option'),
        );
      });
    });

    this._chips.forEach(chip => {
      if (!nestedChips.has(chip)) {
        this.updates.push(
          {
            location: chip.startSourceSpan.start,
            updateFn: html => replaceStartTag(html, chip, 'mat-chip-option'),
          },
          {
            location: chip.startSourceSpan.start,
            updateFn: html => replaceEndTag(html, chip, 'mat-chip-option'),
          },
        );
      }
    });

    return this.updates;
  }

  override reset(): void {
    super.reset();
    this._chipInputAttrs = [];
    this._chipLists = [];
    this._chips = [];
  }

  /** Collects all of the mat-chip nodes nested within the given node. */
  private _collectNestedChips(
    node: compiler.TmplAstElement,
    result: compiler.TmplAstElement[],
  ): void {
    node.children.forEach(child => {
      if (child instanceof compiler.TmplAstElement) {
        if (child.name === 'mat-chip') {
          result.push(child);
        }
        this._collectNestedChips(child, result);
      }
    });
  }

